  const resolved = path.resolve(DATA_DIR, input);
  const relative = path.relative(DATA_DIR, resolved);
  if (relative.length === 0) {
    throw new Error('path must point to a file inside the data directory');
  }
  if (relative.startsWith('..') || path.isAbsolute(relative)) {
    throw new Error('path must not traverse outside the data directory');
  }
  return relative;
}

export async function listTools() {
  return TOOLS;
}

export async function callTool(name, args) {
  if (name !== 'file_metadata') {
    throw new Error(`Unknown tool: ${name}`);
  }
  if (args === null || typeof args !== 'object' || Array.isArray(args)) {
    throw new Error('arguments must be an object');
  }
  const { path: rawPath, ...rest } = args;
  for (const key of Object.keys(rest)) {
    throw new Error(`Unknown argument: ${key}`);
  }
  const safeRelative = resolveSafePath(rawPath);

  const absolute = path.join(DATA_DIR, safeRelative);
  let stat;
  try {
    stat = await fs.stat(absolute);
  } catch (err) {
    if (err && err.code === 'ENOENT') {
      throw new Error(`File not found: ${safeRelative}`);
    }
    throw err;
  }
  if (!stat.isFile()) {
